import { gsap } from 'gsap';
import { Group } from 'three/webgpu';

export default function createNode(config, ctx) {
  const root = new Group();

  // Store for cleanup
  const cleanupTasks = [];

  // Load GLB mesh asynchronously
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      root.add(gltf.scene);
    });
  }

  // Apply cinematic primitives
  const primitiveInstances = [];
  const primitivesConfig = config.cinematicPrimitives || [];
  for (const prim of primitivesConfig) {
    const instance = ctx.primitives[prim.name]?.(root, prim.params);
    if (instance) {
      primitiveInstances.push(instance);
      if (instance.cleanup) cleanupTasks.push(() => instance.cleanup());
    }
  }

  // Event handlers container
  root.userData.handlers = {};

  // Hover lift effect (rise-in)
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(root.position, {
    y: '+=0.15',
    duration: 0.7,
    ease: 'power3.out',
  });
  cleanupTasks.push(() => hoverTimeline.kill());

  root.userData.handlers.hover = () => {
    hoverTimeline.play();
  };
  root.userData.handlers.unhover = () => {
    hoverTimeline.reverse();
  };

  // Click emit
  root.userData.handlers.click = () => {
    ctx.emit('hub-home.select', {});
  };

  // Cleanup method
  root.userData.cleanup = () => {
    cleanupTasks.forEach((fn) => fn());
    // Dispose any GLB resources if needed (handled by GLTF loader cache)
  };

  return root;
}
